<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import QRCode from 'qrcode'
import { api } from './api/client'
import type { Asset, Profile, Wallet, Tx, Quote } from './api/types'
import { formatAmount } from './lib/amount'
const router=useRouter(),route=useRoute();const locked=ref(true),profile=ref<Profile>('test'),wallets=ref<Wallet[]>([]),selected=ref(''),page=ref('home'),password=ref(''),error=ref(''),busy=ref(false),history=ref<Tx[]>([]),filter=ref<Asset|'ALL'>('ALL'),asset=ref<Asset>('BTC'),recipient=ref(''),amount=ref(''),quote=ref<Quote>(),passphrase=ref(''),name=ref('Новый кошелёк'),seed=ref(''),mnemonic=ref(''),wordCount=ref<12|24>(12),mode=ref<'create'|'import'>('create'),step=ref(1),challengePositions=ref<number[]>([]),challengeAnswers=ref<[string,string,string]>(['','','']),qr=ref(''),address=ref(''),timeout=ref(5),newName=ref(''),notice=ref(''),refreshingId=ref('');const current=computed(()=>wallets.value.find(w=>w.id===selected.value));const assets:Asset[]=['BTC','ETH','USDC','USDT'];const seedVisible=ref(false)
const clipboard=navigator.clipboard
watch(page,p=>{const path=p==='home'?'/':'/'+p;if(route.path!==path)void router.replace(path)})
watch(()=>route.path,p=>{const next=p==='/'?'home':p.slice(1);if(next&&next!==page.value)page.value=next})
watch(page,(next,previous)=>{if(previous==='wizard'&&next!=='wizard'){seed.value='';mnemonic.value='';seedVisible.value=false;challengePositions.value=[];challengeAnswers.value=['','',''];password.value='';passphrase.value=''}if(['send','review','confirm'].includes(previous)&&!['send','review','confirm'].includes(next)){password.value='';passphrase.value=''}})
function startWizard(){seed.value='';mnemonic.value='';seedVisible.value=false;challengePositions.value=[];challengeAnswers.value=['','',''];password.value='';passphrase.value='';error.value='';step.value=1;page.value='wizard'}async function refresh(){try{const s=await api.session();locked.value=s.locked;profile.value=s.profile;timeout.value=s.timeout;if(!s.locked){wallets.value=await api.wallets();if(!selected.value&&wallets.value[0])selected.value=wallets.value[0].id}}catch(e){error.value=String(e)}}
async function unlock(){busy.value=true;error.value='';try{await api.unlock(password.value);password.value='';await refresh();page.value='home'}catch{error.value='Не удалось разблокировать. Проверьте пароль.';password.value=''}finally{busy.value=false}}
async function lock(){await api.lock();locked.value=true;wallets.value=[];password.value='';seed.value='';mnemonic.value='';passphrase.value='';seedVisible.value=false;challengePositions.value=[];challengeAnswers.value=['','',''];page.value='lock'}
async function loadHistory(){if(selected.value)history.value=await api.history(selected.value,filter.value==='ALL'?undefined:filter.value)}
async function refreshWallet(id:string){refreshingId.value=id;selected.value=id;error.value='';try{const results=await Promise.allSettled(assets.map(a=>api.refresh(id,a)));wallets.value=await api.wallets();const failed=results.flatMap((result,index)=>result.status==='rejected'?[assets[index]]:[]);if(failed.length)error.value='Не удалось обновить: '+failed.join(', ')+'. Остальные балансы обновлены.'}catch{error.value='Не удалось обновить балансы кошелька.'}finally{refreshingId.value=''}}
async function showReceive(a:Asset){asset.value=a;address.value=await api.receive(selected.value,a);qr.value=await QRCode.toDataURL(address.value,{width:220,margin:1});page.value='receive'}
function buildMnemonicChallenge(value:string){const words=value.trim().split(/\s+/);const indexes=new Set<number>();while(indexes.size<3&&indexes.size<words.length){const random=new Uint32Array(1);crypto.getRandomValues(random);indexes.add(random[0]!%words.length)}challengePositions.value=[...indexes].sort((a,b)=>a-b);challengeAnswers.value=['','','']}function verifyMnemonic(){const words=mnemonic.value.trim().split(/\s+/);const valid=challengePositions.value.every((position,index)=>words[position]?.toLowerCase()===challengeAnswers.value[index]?.trim().toLowerCase());if(!valid){error.value='Слова не совпали. Проверьте seed-фразу и попробуйте ещё раз.';return}mnemonic.value='';seedVisible.value=false;challengePositions.value=[];challengeAnswers.value=['','',''];name.value='Новый кошелёк';step.value=1;error.value='';page.value='home'}async function createWallet(){error.value='';if(!name.value.trim()||password.value.length<10){error.value='Название обязательно, пароль — не менее 10 символов.';return}if(mode.value==='import'&&![12,24].includes(seed.value.trim().split(/\s+/).length)){error.value='Введите seed из 12 или 24 слов';return}busy.value=true;try{if(mode.value==='create'){const result=await api.createWallet(name.value,wordCount.value,password.value,passphrase.value);wallets.value.push(result.wallet);selected.value=result.wallet.id;mnemonic.value=result.mnemonic;buildMnemonicChallenge(result.mnemonic);seedVisible.value=false;step.value=4;password.value='';passphrase.value=''}else{const wallet=await api.importWallet(name.value,seed.value.trim(),password.value,passphrase.value);wallets.value.push(wallet);selected.value=wallet.id;seed.value='';password.value='';passphrase.value='';name.value='';page.value='home'}}catch{error.value=mode.value==='create'?'Не удалось создать кошелёк.':'Не удалось импортировать кошелёк. Проверьте seed и пароль.'}finally{busy.value=false;password.value='';passphrase.value='';if(mode.value==='import')seed.value=''}}
async function prepare(){error.value='';busy.value=true;try{quote.value=await api.prepare(selected.value,asset.value,recipient.value,amount.value);page.value='review'}catch{error.value='Проверьте адрес и сумму.'}finally{busy.value=false}}
async function send(){if(!quote.value)return;busy.value=true;try{await api.confirm(quote.value.draftId,password.value,passphrase.value);password.value='';passphrase.value='';await loadHistory();page.value='history'}catch{error.value='Операция не подтверждена.';password.value='';passphrase.value=''}finally{busy.value=false}}
async function setProfile(p:Profile){await api.profile(p);profile.value=p;await refresh()}async function rename(){if(current.value&&newName.value.trim()){await api.rename(selected.value,newName.value.trim());await refresh();notice.value='Название сохранено'}}async function backup(){try{await api.backup(password.value);notice.value='Запрос резервной копии выполнен'}catch{notice.value='Не удалось создать резервную копию'}finally{password.value=''}}async function copyAddress(){await clipboard.writeText(address.value)}
let refreshTimer:ReturnType<typeof setInterval>|undefined
onMounted(async()=>{await refresh();refreshTimer=setInterval(()=>{if(!locked.value)void refreshAll()},300000)})
async function refreshAll(){for(const wallet of wallets.value)await refreshWallet(wallet.id)}
onBeforeUnmount(()=>{if(refreshTimer)clearInterval(refreshTimer);password.value='';passphrase.value='';seed.value='';mnemonic.value='';challengeAnswers.value=['','',''];challengePositions.value=[]})
</script>
<template><main v-if="locked" class="lock"><section class="card lock-card"><div class="logo">W</div><p class="muted">ЛОКАЛЬНЫЙ НЕКАСТОДИАЛЬНЫЙ КОШЕЛЁК</p><h1>Кошелёк заблокирован</h1><form @submit.prevent="unlock"><label>Пароль</label><input v-model="password" type="password" autocomplete="off" autofocus required><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy">Разблокировать</button></form><span class="badge">ТЕСТОВАЯ СЕТЬ</span></section></main><div v-else class="layout"><aside><div class="brand"><b>W</b> Wallet</div><span class="badge" :class="{main:profile==='main'}">{{profile==='test'?'ТЕСТОВАЯ СЕТЬ':'MAINNET'}}</span><nav><button @click="page='home'">⌂ Обзор</button><button @click="startWizard">＋ Добавить кошелёк</button><button @click="page='history';loadHistory()">↔ История</button><button @click="page='settings'">⚙ Настройки</button></nav><button class="quiet" @click="lock">Заблокировать ↪</button></aside><main class="content"><header><div><small>NON-CUSTODIAL DESKTOP WALLET</small><h1>{{page==='home'?'Ваши активы':page==='wizard'?'Добавить кошелёк':page==='receive'?'Получение':page==='send'||page==='review'||page==='confirm'?'Отправка':page==='history'?'История операций':page==='settings'?'Настройки':'Кошелёк'}}</h1></div><span class="network">{{profile==='test'?'Bitcoin testnet · Sepolia · Nile':'Bitcoin · Ethereum · TRON'}}</span></header>
<section v-if="page==='home'" class="stack"><p v-if="error" class="error">{{error}}</p><div class="heading"><div><h2>Кошельки</h2><p class="muted">Баланс и обновление по каждому активу</p></div><button class="primary" @click="startWizard">＋ Добавить</button></div><article v-for="w in wallets" :key="w.id" class="card"><div class="heading"><h3>{{w.name}}</h3><div class="row"><button class="secondary" :disabled="refreshingId===w.id" @click="refreshWallet(w.id)">{{refreshingId===w.id?'Обновление…':'Обновить балансы'}}</button><button class="quiet" @click="selected=w.id;page='wallet'">Открыть →</button></div></div><div class="assets"><div v-for="b in w.balances" :key="b.asset" class="asset"><small>{{b.network}}</small><b>{{b.asset}}</b><strong>{{formatAmount(b.amount,b.decimals)}} <small>{{b.asset}}</small></strong><small class="muted">Обновлено {{new Date(b.updatedAt).toLocaleTimeString('ru-RU')}}</small><button class="secondary" @click="selected=w.id;showReceive(b.asset)">Получить</button></div></div></article><div v-if="!wallets.length" class="card empty">Кошельков пока нет. Создайте или импортируйте seed.</div></section>
<section v-else-if="page==='wizard'" class="stack narrow"><div class="steps">{{step<=3?`Шаг ${step} из 3`:step===4?'Сохранение seed':'Проверка seed'}}</div><article class="card stack"><template v-if="step===1"><h2>Как добавить кошелёк?</h2><div class="row"><button :class="{selected:mode==='create'}" @click="mode='create'">Создать новый</button><button :class="{selected:mode==='import'}" @click="mode='import'">Импортировать</button></div><label>Название</label><input v-model="name" autocomplete="off"><button class="primary" @click="step=2">Продолжить</button></template><template v-else-if="step===2"><h2>{{mode==='create'?'Параметры seed':'Импорт seed'}}</h2><p class="warning">Никому не сообщайте seed-фразу. Она даёт полный доступ к средствам.</p><template v-if="mode==='create'"><label>Количество слов</label><select v-model.number="wordCount"><option :value="12">12 слов</option><option :value="24">24 слова</option></select><p class="muted">Фраза будет сгенерирована Go после создания кошелька и показана один раз.</p></template><textarea v-else v-model="seed" rows="4" autocomplete="off" spellcheck="false" placeholder="Введите 12 или 24 слова"></textarea><button class="primary" @click="step=3">Продолжить</button></template><template v-else-if="step===3"><h2>Защитите кошелёк</h2><label>Пароль (минимум 10 символов)</label><input v-model="password" type="password" autocomplete="off"><label>Парольная фраза BIP39 (необязательно)</label><input v-model="passphrase" type="password" autocomplete="off"><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy" @click="createWallet">{{mode==='create'?'Создать кошелёк':'Импортировать кошелёк'}}</button></template><template v-else-if="step===4"><h2>Запишите seed-фразу</h2><p class="warning">Сохраните её офлайн. Любой, кто узнает эту фразу, получит доступ к средствам.</p><p v-if="seedVisible" class="seed">{{mnemonic}}</p><button class="secondary" @click="seedVisible=!seedVisible">{{seedVisible?'Скрыть фразу':'Показать seed-фразу'}}</button><p class="muted">Фраза скрыта по умолчанию, не копируется автоматически и будет очищена после проверки.</p><button class="primary" :disabled="!seedVisible" @click="step=5;error=''">Перейти к проверке слов</button></template><template v-else><h2>Проверьте запись</h2><p class="muted">Введите слова из seed-фразы по указанным позициям.</p><label v-for="(position,index) in challengePositions" :key="position">Слово №{{position+1}}<input v-model="challengeAnswers[index]" autocomplete="off" autocapitalize="none" spellcheck="false"></label><p v-if="error" class="error">{{error}}</p><button class="primary" @click="verifyMnemonic">Подтвердить seed</button><button class="quiet" @click="step=4;error='';challengeAnswers=['','','']">Показать фразу ещё раз</button></template><button v-if="step<4" class="quiet" @click="step=Math.max(1,step-1)">← Назад</button></article></section>
<section v-else-if="page==='wallet'" class="stack"><div class="heading"><h2>{{current?.name}}</h2><button class="primary" @click="page='send'">Отправить</button></div><div class="assets"><article v-for="b in current?.balances" :key="b.asset" class="card asset"><small>{{b.network}}</small><h3>{{b.asset}}</h3><strong>{{formatAmount(b.amount,b.decimals)}} {{b.asset}}</strong><button class="secondary" @click="showReceive(b.asset)">Получить {{b.asset}}</button></article></div></section>
<section v-else-if="page==='receive'" class="card narrow stack"><h2>Получить {{asset}}</h2><p class="warning">Принимайте только {{asset}} в правильной сети.</p><span class="network">{{asset==='BTC'?'Bitcoin testnet':asset==='USDT'?'TRON Nile':'Ethereum Sepolia'}}</span><img v-if="qr" :src="qr" class="qr" alt="QR-код адреса"><code class="seed">{{address}}</code><button class="primary" @click="copyAddress">Скопировать адрес</button><button class="quiet" @click="page='wallet'">Назад</button></section>
<section v-else-if="page==='send'" class="card narrow stack"><h2>Новый перевод</h2><label>Актив</label><select v-model="asset"><option v-for="a in assets" :key="a">{{a}}</option></select><label>Адрес получателя</label><input v-model="recipient" autocomplete="off" spellcheck="false"><label>Сумма</label><input v-model="amount" inputmode="decimal" autocomplete="off"><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy" @click="prepare">Проверить перевод</button></section>
<section v-else-if="page==='review'&&quote" class="card narrow stack"><h2>Проверьте перевод</h2><dl><dt>Сеть</dt><dd>{{quote.network}}</dd><dt>Актив</dt><dd>{{quote.asset}}</dd><dt>Получатель</dt><dd class="break">{{quote.recipient}}</dd><dt>Сумма</dt><dd>{{quote.amount}} {{quote.asset}}</dd><dt>Комиссия</dt><dd>{{quote.fee}} {{quote.feeAsset}}</dd></dl><p v-for="w in quote.warnings" :key="w" class="warning">{{w}}</p><button class="primary" @click="page='confirm'">Далее</button></section>
<section v-else-if="page==='confirm'" class="card narrow stack"><h2>Подтверждение</h2><label>Пароль</label><input v-model="password" type="password" autocomplete="off"><label>Парольная фраза BIP39</label><input v-model="passphrase" type="password" autocomplete="off"><p class="warning">Go повторно проверяет намерение, комиссию и подпись.</p><p v-if="error" class="error">{{error}}</p><button class="primary" :disabled="busy" @click="send">Подписать и отправить</button></section>
<section v-else-if="page==='history'" class="stack"><div class="heading"><h2>История</h2><select v-model="filter" @change="loadHistory"><option value="ALL">Все активы</option><option v-for="a in assets" :key="a">{{a}}</option></select></div><article class="card"><p v-if="!history.length" class="muted">Операций пока нет.</p><div v-for="tx in history" :key="tx.id" class="tx"><b>{{tx.asset}} · {{tx.direction==='in'?'Входящая':'Исходящая'}}</b><span>{{tx.amount}} · {{tx.status}}</span><small>{{tx.address}}</small></div></article></section>
<section v-else-if="page==='settings'" class="stack narrow"><article class="card stack"><h2>Профиль сети</h2><div class="row"><button :class="{selected:profile==='test'}" @click="setProfile('test')">Тестовые сети</button><button :class="{selected:profile==='main'}" @click="setProfile('main')">Основные сети</button></div><p v-if="profile==='test'" class="warning">Bitcoin testnet · Ethereum Sepolia · TRON Nile</p></article><article class="card stack"><h2>Автоблокировка</h2><select v-model.number="timeout" @change="api.timeout(timeout)"><option :value="1">1 минута</option><option :value="5">5 минут</option><option :value="10">10 минут</option><option :value="15">15 минут</option><option :value="30">30 минут</option></select></article><article class="card stack"><h2>Управление кошельком</h2><input v-model="newName" placeholder="Новое название"><button class="secondary" @click="rename">Переименовать выбранный</button><label>Пароль для резервной копии</label><input v-model="password" type="password" autocomplete="off"><button class="secondary" @click="backup">Создать резервную копию</button><p>{{notice}}</p></article></section>
</main></div></template>
